sources.src/invoice.ts:
import { priceInvoice } from './pricing.js';
export function submitInvoice(quantity: number) {
  const amount = priceInvoice(quantity);
  return { invoiceTotal: amount };
}

sources.src/pricing.ts:
import { billingPolicy } from './policy.js';
export function priceInvoice(quantity: number) {
  const base = quantity * billingPolicy.unitPrice;
  return base * (1 + billingPolicy.taxRate);
}

sources.src/delivery.ts:
import { sendParcel } from './transport.js';
export function dispatchParcel(address: string) {
  const receipt = sendParcel(address);
  return { trackingCode: receipt.id };
}

sources.src/transport.ts:
import { deliveryPolicy } from './delivery-policy.js';
export function sendParcel(address: string) {
  const attempts = deliveryPolicy.retryLimit;
  return { id: address + ':' + attempts };
}

